using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Globalization;using System.Collections.Generic;using System.Web.Script.Serialization;
namespace SidebarAgentLifecycle {
 public sealed class Reader {
  public static readonly string DefaultRoot=System.IO.Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.LocalApplicationData), @"StatusIsland\status-sources\agents");
  readonly string root;readonly Func<Receipt,bool?> check;readonly Dictionary<string,View> cache=new Dictionary<string,View>();readonly Dictionary<string,DateTimeOffset> cachedAt=new Dictionary<string,DateTimeOffset>();readonly HashSet<string> denied=new HashSet<string>();
  public Reader(string sourceRoot=null,Func<Receipt,bool?> verifier=null){root=sourceRoot??DefaultRoot;check=verifier??VerifyOwner;}
  static string Str(Dictionary<string,object>d,string k){object v;return d!=null&&d.TryGetValue(k,out v)?v as string:null;}
  static string ReadSmall(string file,int maximum){EventStore.Plain(file);if(!File.Exists(file)||new FileInfo(file).Length>maximum)return null;using(var stream=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete)){var bytes=new byte[maximum+1];int total=0,n;while(total<bytes.Length&&(n=stream.Read(bytes,total,bytes.Length-total))>0)total+=n;if(total>maximum)return null;return new System.Text.UTF8Encoding(false,true).GetString(bytes,0,total);}}
  string Expected(string provider){string raw=ReadSmall(Path.Combine(root,"connection.json"),8192);if(raw==null)return null;var d=new JavaScriptSerializer{MaxJsonLength=8192,RecursionLimit=8}.DeserializeObject(raw) as Dictionary<string,object>;object approved,providers,spec;if(d==null||Str(d,"schema")!="sidebar.agent-connection.v1"||!d.TryGetValue("approved",out approved)||!(approved is bool)||!(bool)approved||!d.TryGetValue("providers",out providers))return null;var map=providers as Dictionary<string,object>;if(map==null||!map.TryGetValue(provider,out spec))return null;return Str(spec as Dictionary<string,object>,"ownerExecutable");}
  bool? VerifyOwner(Receipt receipt){string key=receipt.ownerPid+":"+receipt.ownerBirthUtc;if(denied.Contains(key))return null;try{using(var process=Process.GetProcessById(receipt.ownerPid)){if(process.HasExited||process.StartTime.ToUniversalTime().Ticks!=DateTimeOffset.Parse(receipt.ownerBirthUtc).UtcDateTime.Ticks)return false;return String.Equals(Path.GetFullPath(process.MainModule.FileName),Path.GetFullPath(receipt.ownerExecutable),StringComparison.OrdinalIgnoreCase);}}catch(ArgumentException){return false;}catch(InvalidOperationException){return false;}catch(UnauthorizedAccessException){denied.Add(key);return null;}catch(System.ComponentModel.Win32Exception e){if(e.NativeErrorCode==5)denied.Add(key);return null;}catch{return null;}}
  public View Read(string provider,DateTimeOffset now){if(provider!="codex"&&provider!="claude-code")return new View();View old;DateTimeOffset at;if(cache.TryGetValue(provider,out old)&&cachedAt.TryGetValue(provider,out at)&&(now-at).TotalSeconds>=0&&(now-at).TotalSeconds<1)return old;var result=new View{CheckedAt=now};try{string expected=Expected(provider);if(String.IsNullOrWhiteSpace(expected)||!Path.IsPathRooted(expected))return result;string folder=Path.Combine(root,provider);EventStore.Plain(folder);if(!Directory.Exists(folder))return result;var files=Directory.EnumerateFiles(folder,"*.json").Take(1025).Select(f=>new FileInfo(f)).OrderByDescending(f=>f.LastWriteTimeUtc).Take(128).ToArray();var records=new List<Receipt>();bool incomplete=false;foreach(var file in files){var record=Lifecycle.ParseReceipt(ReadSmall(file.FullName,4096),provider);if(record==null||Path.GetFileNameWithoutExtension(file.Name)!=record.sessionHash||!String.Equals(Path.GetFullPath(expected),Path.GetFullPath(record.ownerExecutable),StringComparison.OrdinalIgnoreCase)){incomplete=true;continue;}records.Add(record);}result=Lifecycle.Reduce(provider,records,check,now);if(incomplete&&result.State=="idle")result.State="unknown";}catch{result=new View{CheckedAt=now};}finally{cache[provider]=result;cachedAt[provider]=now;}return result;}
 }
}
